    version: "庚辰本（第五回）",
    original: [
      "可叹停机德，堪怜咏絮才。",
      "玉带林中挂，金簪雪里埋。"
    ],
    translation: [
      "可叹那具有停机断织之德的宝钗，堪怜那具有咏絮之才的黛玉。",
      "黛玉如玉带悬挂于枯木之上，宝钗似金簪埋没于冰雪之中。"
    ],
    gloss: [
      { term: "停机德", note: "用乐羊子妻割断织布机上的经线劝夫求学之典，借指薛宝钗恪守封建妇德。" }, { term: "咏絮才", note: "用东晋谢道韫以'未若柳絮因风起'咏雪之典，借指林黛玉出众的诗才。" }, { term: "玉带林", note: "'玉带林'三字倒读即'林黛玉'，暗示黛玉之名及其命运。" }, { term: "金簪雪", note: "'金簪雪'暗含'薛宝钗'之意，金簪即宝钗，雪谐音薛。" }
    ],
    analysis: [
      "这是金陵十二钗正册第一首判词，将林黛玉与薛宝钗合为一判，二人一才一德、一木一金，形成鲜明对照。诗以'可叹''堪怜'起笔，定下全诗惋惜哀悯的基调，既赞宝钗之德、又怜黛玉之才，却又预示二人皆不得善终。",
      "'玉带林中挂'与'金簪雪里埋'两句用拆字、谐音之法，将二女之名嵌入诗中。玉带挂于枯木，暗示黛玉泪尽而亡、孤悬无依；金簪埋于冰雪，暗示宝钗虽成金玉良缘却终归冷落寂寞。两人各有所长、各有所憾，殊途同归于薄命，正是'千红一哭，万艳同悲'的缩影。"
    ],
    pullquote: "玉带林中挂，金簪雪里埋。",
