      "'清明涕送江边望，千里东风一梦遥'描绘远嫁别离之景，清明本为思亲祭祖之节，探春却于此时远行，江边涕泪、东风千里，将'生离'之痛写得苍凉辽远。'一梦遥'三字，暗示此去如梦，再无归期。"
