      "'好一似食尽鸟投林，落了片白茫茫大地真干净'是全书最著名的结语，以飞鸟食尽散去喻贾府树倒猢狲散，'白茫茫大地真干净'七字，将一场繁华写得彻彻底底归于虚无。十二支曲以此收束，千红万艳皆归白茫茫一片，正是红楼梦的终极意境。"
