    analysis: [
      "此首作于宝玉挨打后遣晴雯送两条旧手帕与黛玉之时。黛玉体会宝玉深意，感其知己之情，遂在手帕上题下三绝。开篇“眼空蓄泪泪空垂”直写流泪之态，“空”字两见，写出泪之徒然与情之无奈。“暗洒闲抛却为谁”以反问深化伤感，无人可诉。",
      "后两句转写手帕本身，“尺幅鲛绡”既写实物又用鲛人泣珠之典，暗示黛玉以泪还债的前生宿缘。“劳解赠”三字写宝玉赠帕之殷，“叫人焉得不伤悲”以反诘收束，情真意切，将知己之感与身世之悲融为一体。"
    ],
    pullquote: "眼空蓄泪泪空垂，暗洒闲抛却为谁。",
