      "后两句“枕上袖边难拂拭，任他点点与斑斑”写泪痕无处不染，索性任其斑驳。“任他”二字写出无可奈何的放任，看似消极，实是深情无可排遣。此首与黛玉“泪尽而亡”的命运遥相呼应，伏笔深远。"
