      "'行为偏僻性乖张，那管世人诽谤'是全词精神所在，道出宝玉反抗封建礼教、我行我素的叛逆性格。作者借这首词预先为宝玉定性，与后文他种种'乖张'行为相呼应，是理解宝玉这一人物形象的关键。词中'好皮囊'与'草莽'的对照，也预示了他'金玉其外'却难容于世的悲剧命运。"
