  baoyu_jiyu: {
    title: "宝玉偈语",
    type: "偈语",
    author: "贾宝玉",
    chapter: "第二十二回",
    original: [
      "你证我证，心证意证。",
      "是无有证，斯可云证。",
      "无可云证，是立足境。"
    ],
    translation: [
      "\"你证我证，心证意证\"——你我互相印证，心念与意识互相印证；\"是无有证，斯可云证\"——当不再执着于印证之时，才可说是真正的印证；\"无可云证，是立足境\"——到了无可言说、无可印证的境地，便是安身立命之处。"
    ],
    gloss: [
      { term: "证", note: "佛教语，印证、证悟，指以心印证真理、证得道果。此处引申为相互理解、彼此印证心思。" }, { term: "无可云证", note: "没有什么可以称作印证，即超越一切相待印证的境界。" }, { term: "立足境", note: "安身立命的境地。佛教谓证得空性之后，方能找到真正安身立命之处。" }
    ],
    analysis: [
      "此偈作于第二十二回。宝钗生日时点戏《鲁智深醉闹五台山》（即《山门》），宝玉听曲文至\"赤条条来去无牵挂\"一句，大为赞赏。后又因在湘云、黛玉之间调解反而两头不讨好，心生烦恼，遂借禅机写下此偈，意谓彼此印证来印证去，终须到无可印证之处，方能找到立足之境，流露出出世离群之意。",
      "黛玉见后，续以\"无立足境，是方干净\"，比宝玉更进一步，连\"立足境\"亦予否定；宝钗又引六祖慧能\"菩提本无树\"之公案点破，谓宝玉并未真正彻悟。可见此偈实为宝玉\"悟禅机\"的初萌，却尚未达到彻底解脱之境，正映其日后出家前的一段心路。"
    ],
    pullquote: "无可云证，是立足境。",
    related: [
      { label: "续作", titles: "黛玉续偈：无立足境，是方干净" }
    ]
  },

