    translation: [
      "此诗为大观园众人在芦雪庵赏雪、烤鹿肉后即景联句所作，共三十五韵七十句。凤姐以'一夜北风紧'起句，众人依次接对。前半部分每人联一对句并出一新句；后半部分湘云、黛玉、宝琴三人争相抢联，每人只联一句。全诗为五言排律，以二萧韵一韵到底，铺写大雪之夜的种种景象：从飞雪入泥、寒山冻浦，到麝煤宝鼎、绮袖金貂，从野岸孤棹、吟鞭灞桥，到石楼睡鹤、锦罽亲猫，最后以'欲志今朝乐，凭诗祝舜尧'作结，极尽铺张渲染之能事。"
    ],
    gloss: [
      { term: "联句", note: "多人合作作诗的一种方式。由一人起句，余人依次接对，通常用排律形式。此诗前半每人联一对句并出一新句，后半众人抢联，每人只联一句，以显兴高争先之态。" }, { term: "芦雪庵", note: "大观园中傍山临水的建筑，四面芦苇掩覆，故名。庚辰本作'芦雪广'，'广'音yǎn，指就山崖建造的房屋，非'广'之简化字。" }, { term: "即景", note: "就眼前景物即兴赋诗。此诗即就芦雪庵赏雪之景而作，故称'即景联句'。" }
    ],
    analysis: [
      "此联句为大观园中最热闹的诗事之一，参加者多达十二人。凤姐以'一夜北风紧'起句，众人皆赞'这句虽粗，不见底下的，这正是会作诗的起法'，此后依次联句，由李纨、香菱、探春、李绮、李纹、岫烟、湘云、宝琴、黛玉、宝玉、宝钗等轮流接对。联到后半，湘云、黛玉、宝琴三人争相抢联，不顾联句规矩，湘云甚至'笑软了'伏在宝钗怀里，宝钗推她起道'你有本事把二箫的韵全用完了，我才伏你'。全诗为五言排律，共三十五韵，以二萧韵一韵到底，从凤姐的粗话起句到李绮'凭诗祝舜尧'收结，铺写了大雪中的种种景致与情怀。联句诗本是文字游戏，难免堆砌，但曹雪芹借这场热闹盛会，既展现了大观园群芳的才情，又渲染了'极盛'之象——而盛极必衰，这场盛事恰是贾府由盛转衰前最后的繁华。"
    ],
    pullquote: "一夜北风紧。",
