      "第二年流寇席卷山东，势如蜂拥、强吞虎豹。恒王率天兵意图剿灭，一战再战都不能成功。腥风吹折陇头麦子，日照旌旗而虎帐已空——青山寂寂、流水澌澌，正是恒王战死之时；雨淋白骨、血染青草，月冷黄沙、鬼守尸骸。众将士纷纷只顾保身，青州眼见将成灰尘。不料忠义竟彰明于闺阁，愤然而起的正是恒王得意的林四娘。她号令秦姬、驱遣赵女，艳李秾桃直临战场；绣鞍有泪、春愁沉重，铁甲无声、夜气凄凉。胜负本难预定，她们誓盟生死以报前王；贼势猖獗不可敌，柳折花残实可伤。魂依城郭、家乡已近，马践胭脂、骨髓生香。星驰报入京师，谁家儿女不伤悲！天子惊慌恨其失守，此时文武皆垂首。为何文武立朝纲，反不及闺中林四娘？我为四娘长长叹息，歌成之后余意仍彷徨。"
